WHERE h.DELETED_YN = 'N' AND l.DELETED_YN = 'N'
AND h.BUSINESS_DATE >= TO_DATE(#{startDate}, 'YYYY-MM-DD')
AND h.BUSINESS_DATE < TO_DATE(#{endDate}, 'YYYY-MM-DD') + 1
AND h.PROGRESS_STATUS = #{progressStatus}
AND h.WAREHOUSE_ID IN
#{warehouseId}
AND h.PARTNER_ID IN
#{partnerId}
AND l.ITEM_ID IN
#{itemId}
AND ( UPPER(h.SALE_NO) LIKE '%' || UPPER(#{keyword}) || '%' OR TO_CHAR(h.BUSINESS_DATE, 'YYYY-MM-DD') LIKE '%' || #{keyword} || '%' OR TO_CHAR(h.BUSINESS_DATE, 'YYYY/MM/DD') LIKE '%' || #{keyword} || '%' OR UPPER(h.PARTNER_NAME) LIKE '%' || UPPER(#{keyword}) || '%' OR UPPER(h.ASSIGNEE_NAME) LIKE '%' || UPPER(#{keyword}) || '%' OR UPPER(h.WAREHOUSE_NAME) LIKE '%' || UPPER(#{keyword}) || '%' OR UPPER(source_header.SALES_ORDER_NO) LIKE '%' || UPPER(#{keyword}) || '%' OR TO_CHAR(source_header.BUSINESS_DATE, 'YYYY-MM-DD') LIKE '%' || #{keyword} || '%' OR TO_CHAR(source_header.BUSINESS_DATE, 'YYYY/MM/DD') LIKE '%' || #{keyword} || '%' OR UPPER(i.ITEM_CODE) LIKE '%' || UPPER(#{keyword}) || '%' OR UPPER(l.ITEM_NAME) LIKE '%' || UPPER(#{keyword}) || '%' OR UPPER(l.SPECIFICATION) LIKE '%' || UPPER(#{keyword}) || '%' OR UPPER(l.UNIT) LIKE '%' || UPPER(#{keyword}) || '%' OR UPPER(l.NOTE) LIKE '%' || UPPER(#{keyword}) || '%' )
